import{_ as t,o as e,c as s,a2 as i}from"./chunks/framework.BWuWLRhz.js";const f=JSON.parse('{"title":"命令列搜尋（lff）","description":"","frontmatter":{},"headers":[],"relativePath":"zh-TW/user-guide/cli.md","filePath":"zh-TW/user-guide/cli.md","lastUpdated":1785993908000}'),d={name:"zh-TW/user-guide/cli.md"};function l(p,a,o,r,n,h){return e(),s("div",null,[...a[0]||(a[0]=[i(`<h1 id="命令列搜尋-lff" tabindex="-1">命令列搜尋（lff） <a class="header-anchor" href="#命令列搜尋-lff" aria-label="Permalink to &quot;命令列搜尋（lff）&quot;">​</a></h1><p>Lertaro 還附帶一個小巧的命令列夥伴工具 <strong><code>lff</code></strong>——一個 fzf 風格的模糊搜尋器，搜尋的是 App 本身已經維護好的同一份索引，而不是自己再重新掃描一遍。它是給那些常年待在終端機裡、也希望能用上 Lertaro 那套搜尋能力（模糊比對、拼音別名、網路磁碟，一應俱全）的人準備的，不只是侷限在搜尋視窗裡。</p><p><code>lff</code> 需要 Lertaro App 已經在執行——它是透過一條本機的、按使用者區分的管道跟 App 通訊，而不是自己重新掃一遍。如果 App 沒有執行，<code>lff</code> 會快速失敗，把錯誤訊息輸出到 stderr，而不是卡住不動。</p><h2 id="設定" tabindex="-1">設定 <a class="header-anchor" href="#設定" aria-label="Permalink to &quot;設定&quot;">​</a></h2><p><code>lff.exe</code> 會和 App 一起安裝。在安裝程式的工作選擇頁面勾選<strong>將 lff 命令列搜尋工具加入 PATH</strong>，就能在任意終端機裡直接以 <code>lff</code> 執行——這一步會把 Lertaro 的安裝目錄加進系統 PATH。勾選之後請重新開啟一個終端機視窗；安裝時已經開著的那個不會自動感知到這個變化。</p><p>如果安裝時跳過了這個選項，仍然可以直接從 Lertaro 的安裝目錄裡執行它。</p><h2 id="基本用法" tabindex="-1">基本用法 <a class="header-anchor" href="#基本用法" aria-label="Permalink to &quot;基本用法&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>lff</span></span></code></pre></div><p>會開啟一個互動式選擇介面：打字即可模糊篩選，跟 App 自己的搜尋完全一致——包括中文檔名的拼音別名比對（參見<a href="./search-syntax.html">搜尋語法</a>）。</p><table tabindex="0"><thead><tr><th>按鍵</th><th>作用</th></tr></thead><tbody><tr><td>打字</td><td>篩選結果</td></tr><tr><td>↑ / ↓</td><td>移動高亮項</td></tr><tr><td>Page Up / Page Down</td><td>翻頁</td></tr><tr><td>← / →</td><td>移動查詢文字中的游標</td></tr><tr><td>Tab</td><td>切換選取/取消選取目前高亮的結果（選取的列會顯示 <code>*</code>）</td></tr><tr><td>Enter</td><td>輸出選取的路徑——如果沒有選取任何項目，就輸出目前高亮的那一個——然後結束</td></tr><tr><td>Esc / Ctrl+C</td><td>不輸出任何內容，直接結束</td></tr></tbody></table><h2 id="預先帶入查詢關鍵字" tabindex="-1">預先帶入查詢關鍵字 <a class="header-anchor" href="#預先帶入查詢關鍵字" aria-label="Permalink to &quot;預先帶入查詢關鍵字&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>lff report</span></span></code></pre></div><p>以及</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>echo report | lff</span></span></code></pre></div><p>兩種方式都會以 <code>report</code> 作為初始關鍵字開啟介面並直接篩選。不管哪種方式，這都只是預先帶入查詢框、然後像手動打字一樣觸發同一次搜尋——它自己不會做任何自動選取或自動輸出，你仍然需要自己導覽、按 Enter/Tab 確認。</p><h2 id="多選結果" tabindex="-1">多選結果 <a class="header-anchor" href="#多選結果" aria-label="Permalink to &quot;多選結果&quot;">​</a></h2><p>Tab 用來標記/取消標記目前高亮的這一列。標記狀態會在你變更查詢關鍵字之後依然保留——所以你可以先搜一個檔案標記它，再搜別的檔案繼續標記，以此類推。狀態列會顯示目前一共標記了幾項。只要有標記項，按 Enter 就會輸出所有被標記的路徑（每行一個），跟目前高亮的是哪一項無關。</p><h2 id="把結果用到別的命令裡" tabindex="-1">把結果用到別的命令裡 <a class="header-anchor" href="#把結果用到別的命令裡" aria-label="Permalink to &quot;把結果用到別的命令裡&quot;">​</a></h2><p><code>lff</code> 的互動介面是直接畫在主控台上的，完全不經過標準輸入輸出串流——唯一會真正寫進 stdout 的，只有按 Enter 時輸出的那些最終選取路徑（每行一個）。這也是它能跟常見 shell 技巧組合、把結果傳給別的命令的原因。</p><p>PowerShell：</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">code (lff)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$path </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> lff; code $path</span></span></code></pre></div><p>cmd.exe（沒有內建的命令替換語法，用 <code>for /f</code>）：</p><div class="language-cmd vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cmd</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">for</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /f </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;delims=&quot;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> %</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">i in (</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">&#39;lff&#39;) do code &quot;%i&quot;</span></span></code></pre></div><h2 id="侷限" tabindex="-1">侷限 <a class="header-anchor" href="#侷限" aria-label="Permalink to &quot;侷限&quot;">​</a></h2><ul><li>沒有預覽面板——這是有意為之的取捨，App 自己的<a href="./actions-and-preview.html">動作選單與預覽</a>已經涵蓋了這部分需求。</li><li>需要 Lertaro App 正在執行；<code>lff</code> 自己不會索引任何東西。</li></ul>`,25)])])}const u=t(d,[["render",l]]);export{f as __pageData,u as default};
